<?php defined('BASEPATH') or exit('No direct script access allowed');$project_tasks=$project_tasks??null;$project_task=$project_task??null;$esc=static fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8'); ?>
<section id="portal-project-tasks"><h3>Tarefas publicadas</h3><?php if($project_tasks!==null){foreach($project_tasks['items'] as $task){ ?><p><a href="<?= $esc($task_url((int)$task['id'])); ?>"><?= $esc($task['name']); ?></a> — <?= $esc($task['status']); ?> — <?= $esc($task['due_date']); ?></p><?php }if($project_tasks['next']!==null){ ?><a href="<?= $esc($tasks_page_url((int)$project_tasks['next'])); ?>">Mais tarefas publicadas</a><?php }}if($project_task!==null){ ?><article id="portal-project-task-detail"><h4><?= $esc($project_task['name']); ?></h4><p style="white-space:pre-wrap"><?= $esc($project_task['description']); ?></p><?php if(isset($project_task['assignee_name'])){ ?><p>Responsável: <?= $esc($project_task['assignee_name']); ?></p><?php }if(array_key_exists('comments',$project_task)){ ?><h5>Comentários publicados</h5><?php foreach($project_task['comments'] as $comment){ ?><p style="white-space:pre-wrap"><?= $esc($comment['body']); ?></p><small><?= $esc($comment['created_at']); ?></small><?php }}if(array_key_exists('checklist',$project_task)){ ?><h5>Checklist publicada</h5><?php foreach($project_task['checklist'] as $item){ ?><p><?= $item['done']?'Concluído: ':'Pendente: '; ?><?= $esc($item['text']); ?></p><?php }}if(array_key_exists('total_logged_seconds',$project_task)){ ?><p>Tempo encerrado publicado: <?= (int)$project_task['total_logged_seconds']; ?> segundos</p><?php }if(array_key_exists('files',$project_task)){foreach($project_task['files'] as $file){echo form_open($task_file_url); ?><input type="hidden" name="portal_csrf" value="<?= $esc($portal_csrf); ?>"><input type="hidden" name="action" value="project_task_file"><input type="hidden" name="project_id" value="<?= (int)$project_id; ?>"><input type="hidden" name="task_id" value="<?= (int)$project_task['id']; ?>"><input type="hidden" name="file_key" value="<?= $esc($file['file_key']); ?>"><button type="submit">Baixar <?= $esc($file['filename']); ?></button><?= form_close(); }} ?></article><?php } ?></section>
